def browse_recommendations(self, params: dict[str, Any]) -> dict[str, Any]:
    """Unsupported helper for schemas that are not part of this benchmark.

    The shopping domain is intentionally search-only; recommendation
    requests should be handled through search_products.
    """
    raise RuntimeError("browse_recommendations is not supported. Use search_products.")

def get_promotions(self, params: dict[str, Any]) -> dict[str, Any]:
    """List active promo codes. Optional category filter. No cart coupling."""
    return self.promotion_service.get_promotions(params)

def get_policies(self, params: dict[str, Any]) -> dict[str, Any]:
    topic = params.get("topic", "")
    if topic in POLICY_TEXTS:
        return POLICY_TEXTS[topic]
    return {
        "error": f"Unknown policy topic: '{topic}'. Valid topics: {', '.join(VALID_POLICY_TOPICS)}.",
    }

# -------------------------------------------------------------------
# WRITE tools
# -------------------------------------------------------------------

def add_to_cart(self, params: dict[str, Any]) -> dict[str, Any]:
    """Create a cart_item record for (cart, product). Recompute cart aggregates.

    If the product is already in the cart, increment its quantity instead
    of creating a duplicate cart_item. Quantity limit enforced.

    If the product has variants, a `variant_id` MUST be supplied. Two items
    of the same product but different variants result in separate lines.
    """
    return self.cart_service.add_to_cart(params)

def update_cart_item(self, params: dict[str, Any]) -> dict[str, Any]:
    """Modify quantity and/or gift_wrap for an existing cart_item.

    quantity=0 removes the item (delegates to remove_from_cart semantics).
    At least one of quantity / gift_wrap must be provided.
    """
    return self.cart_service.update_cart_item(params)

def remove_from_cart(self, params: dict[str, Any]) -> dict[str, Any]:
    """Delete the cart_item for (cart, product). Recompute aggregates."""
    return self.cart_service.remove_from_cart(params)

def apply_promo(self, params: dict[str, Any]) -> dict[str, Any]:
    """Validate `promo_code` against current cart and add it to applied codes.

    One promo code can be applied per cart. Applying the same code twice is
    a no-op (deduped); applying a different code requires removing the
    existing code first. Validates intrinsic rules (active, expiry,
    category, min_purchase) — does NOT check customer-fit rules; that's the
    agent's responsibility.
    """
    return self.promotion_service.apply_promo(params)

def remove_promo(self, params: dict[str, Any]) -> dict[str, Any]:
    """Remove a previously applied promo code and recompute totals."""
    return self.promotion_service.remove_promo(params)

def redeem_loyalty_points(self, params: dict[str, Any]) -> dict[str, Any]:
    """Redeem loyalty points for a dollar discount on the current cart total.

    Debits points from customer.loyalty_points. Enforces minimum, balance, and
    50%-of-cart-total cap per the loyalty_redemption policy.
    """
    customer_id = params.get("customer_id", "")
    requested = int(params.get("points") or 0)
    cart = self._resolve_cart(customer_id)
    if cart is None:
        return {"error": f"No cart for customer {customer_id}."}
    customer = self.customers.get(customer_id)
    if customer is None:
        return {"error": f"Customer {customer_id} not found."}
    if cart.subtotal <= 0:
        return {"error": "Cart is empty — cannot redeem points on an empty cart."}
    if cart.loyalty_discount > 0:
        return {
            "error": (

            "error": (
                f"Points already redeemed on this cart ({cart.loyalty_points_redeemed} pts = "
                f"${cart.loyalty_discount}). Cancel first to redeem a different amount."
            )
        }
    result = policies.validate_redemption(
        balance=customer.loyalty_points,
        requested_points=requested,
        cart_total=cart.subtotal + cart.gift_wrap_fee - cart.discount_amount,
    )
    if not result["valid"]:
        return {"error": result["reason"]}

    discount = int(result["discount_amount"])
    points_debited = int(result["points_debited"])
    customer.loyalty_points -= points_debited
    cart.loyalty_discount = discount
    cart.loyalty_points_redeemed = points_debited
    adjustments = self._recompute_cart(cart)
    return {
        "status": "redeemed",
        "points_redeemed": points_debited,
        "discount_applied": discount,
        "remaining_balance": customer.loyalty_points,
        "cart_subtotal": cart.subtotal,
        "cart_total": cart.total,
        **adjustments,
    }

def cancel_loyalty_redemption(self, params: dict[str, Any]) -> dict[str, Any]:
    """Reverse a prior loyalty_points redemption on this cart and credit points back."""
    customer_id = params.get("customer_id", "")
    cart = self._resolve_cart(customer_id)
    if cart is None:
        return {"error": f"No cart for customer {customer_id}."}
    customer = self.customers.get(customer_id)
    if customer is None:
        return {"error": f"Customer {customer_id} not found."}
    if cart.loyalty_discount == 0 and cart.loyalty_points_redeemed == 0:
        return {"error": "No loyalty redemption on this cart to cancel."}
    credited = cart.loyalty_points_redeemed
    customer.loyalty_points += credited
    cart.loyalty_discount = 0
    cart.loyalty_points_redeemed = 0
    adjustments = self._recompute_cart(cart)
    return {
        "status": "cancelled",
        "points_credited": credited,
        "new_balance": customer.loyalty_points,
        "cart_subtotal": cart.subtotal,
        "cart_total": cart.total,
        **adjustments,
    }

def get_shipping_options(self, params: dict[str, Any]) -> dict[str, Any]:
    """List available shipping options for the customer's cart with prices and ETAs.

    Does not mutate cart state. Returns each valid option with `option`,
    `cost`, `eta_description`, and an `eligibility` note explaining any
    tier-based free perk or the 5+-item standard override.
    """
    return self.shipping_service.get_shipping_options(params)

def set_shipping_option(self, params: dict[str, Any]) -> dict[str, Any]:
    """Set the shipping option on the cart. Validates and writes cart.shipping_cost.

    Recomputes cart totals so cart.total reflects the added shipping cost.
    Customers can switch options freely by calling again; the prior value
    is overwritten.
    """
    return self.shipping_service.set_shipping_option(params)

def validate_promo(self, params: dict[str, Any]) -> dict[str, Any]:
    """Pure read — check whether a promo code would validate against the current cart.

    Checks intrinsic validity only (exists, active, not expired, category
    restriction, min_purchase). Does NOT check customer-fit rules like
    first-time-only — that's the agent's job via get_customer_account.
    """
    return self.promotion_service.validate_promo(params)

"""Vendored domain-agnostic base classes (from state_bench). Stdlib only."""
from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class DictMixin:
    """Standard to_dict/from_dict for flat dataclasses."""

    def to_dict(self) -> dict[str, Any]:
        return {fn: getattr(self, fn) for fn in self.__dataclass_fields__}

    @classmethod
    def from_dict(cls, data: dict[str, Any]):
        return cls(**{k: v for k, v in data.items() if k in cls.__dataclass_fields__})


class BaseEnvironment(ABC):
    """Abstract base for domain environments."""

    def __init__(self, env_data: Any, now: str):
        self.now = now

    @property
    @abstractmethod
    def tool_handlers(self) -> dict[str, Callable]:
        ...

    @abstractmethod
    def get_full_snapshot(self) -> dict[str, dict[str, dict[str, Any]]]:
        ...

    @staticmethod
    def parse_bool(value: Any) -> bool | None:
        if value is None:
            return None
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.lower() in ("true", "1", "yes")
        return bool(value)

"""Cart lookup and mutation operations."""

from __future__ import annotations

import re
from typing import Any

import policies
from schemas import Cart, CartItem, Product
from services.pricing import PricingEngine


class CartService:
    """Own cart item lookup, stock checks, ID generation, and mutations."""

    def __init__(
        self,
        *,
        products: dict[str, Product],
        carts_by_id: dict[str, Cart],
        cart_items: dict[str, CartItem],
    ) -> None:
        self.products = products
        self.carts_by_id = carts_by_id
        self.cart_items = cart_items
        self.pricing_engine: PricingEngine | None = None
        self._next_ci_seq = self._initial_ci_seq()

    def set_pricing_engine(self, pricing_engine: PricingEngine) -> None:
        self.pricing_engine = pricing_engine

    def _recompute_cart(self, cart: Cart) -> dict[str, Any]:
        assert self.pricing_engine is not None
        return self.pricing_engine.recompute_cart(cart)

    def _initial_ci_seq(self) -> int:
        max_seq = 0
        for ciid in self.cart_items:
            m = re.match(r"^CI-(\d+)$", ciid)
            if m:
                max_seq = max(max_seq, int(m.group(1)))
        return max_seq + 1

    def next_cart_item_id(self) -> str:
        ciid = f"CI-{self._next_ci_seq:04d}"
        self._next_ci_seq += 1
        return ciid

    def resolve_cart(self, customer_id: str) -> Cart | None:
        return self.carts_by_id.get(f"CART-{customer_id}")

    def items_in_cart(self, cart: Cart) -> list[CartItem]:
        return [self.cart_items[iid] for iid in cart.item_ids if iid in self.cart_items]

    def resolve_cart_item(
        self,
        cart: Cart,
        product_id: str,
        variant_id: str | None = None,
    ) -> tuple[CartItem | None, str | None]:
        matches = [
            ci
            for ci in self.items_in_cart(cart)
            if ci.product_id == product_id and (variant_id is None or ci.variant_id == variant_id)
        ]
        if not matches:
            if variant_id is not None:
                return None, f"Product {product_id} with variant {variant_id} not in cart."
            return None, f"Product {product_id} not in cart."
        if variant_id is None and len(matches) > 1:
            variants = ", ".join(sorted(ci.variant_id or "<none>" for ci in matches))
            return None, f"Multiple variants of product {product_id} are in cart ({variants}); provide variant_id."
        return matches[0], None

    def variant_lookup(self, product: Product, variant_id: str | None) -> dict[str, Any] | None:
        """Find a variant dict on a product by id."""
        if not variant_id or not product.variants:
            return None
        for v in product.variants:
            if v.get("variant_id") == variant_id:
                return v
        return None

    def check_product_stock(
        self,
        product: Product,
        variant_id: str | None,
        requested_quantity: int,
    ) -> tuple[dict[str, Any] | None, str | None]:
        if product.variants:
            if not variant_id:
                return None, (
                    f"{product.name} requires a variant selection. Check product details or variants to see options."
                )
            variant = self.variant_lookup(product, variant_id)
            if variant is None:
                return None, f"Variant '{variant_id}' not found for {product.name}."
            stock = policies.check_stock(
                bool(variant.get("in_stock", True)),
                int(variant.get("stock_quantity", 0)),
                requested_quantity,
            )
            if not stock["available"]:
                return None, stock["reason"]
            return variant, None
        if variant_id:
            return None, f"{product.name} does not have variants."
        stock = policies.check_stock(product.in_stock, product.stock_quantity, requested_quantity)
        if not stock["available"]:
            return None, stock["reason"]
        return None, None

    def add_to_cart(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        product_id = params.get("product_id", "")
        quantity = int(params.get("quantity", 1) or 1)
        gift_wrap = bool(params.get("gift_wrap", False))
        variant_id = params.get("variant_id") or None

        if quantity <= 0:
            return {"error": "quantity must be a positive integer."}

        cart = self.resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}

        product = self.products.get(product_id)
        if product is None:
            return {"error": f"Product {product_id} not found."}

        variant, stock_error = self.check_product_stock(product, variant_id, quantity)
        if stock_error:
            return {"error": stock_error}

        existing: CartItem | None = None
        for ci in self.items_in_cart(cart):
            if ci.product_id == product_id and ci.variant_id == variant_id:
                existing = ci
                break

        if existing is not None:
            final_quantity = existing.quantity + quantity
            qcheck = policies.check_quantity_limit(existing.quantity, quantity)
            if not qcheck["allowed"]:
                return {"error": qcheck["reason"]}
            _variant, stock_error = self.check_product_stock(product, variant_id, final_quantity)
            if stock_error:
                return {"error": stock_error}
            existing.quantity += quantity
            if gift_wrap:
                existing.gift_wrap = True
            adjustments = self._recompute_cart(cart)
            return {
                "status": "updated",
                "cart_item_id": existing.cart_item_id,
                "product_id": product_id,
                "product_name": product.name,
                "variant_id": existing.variant_id,
                "quantity": existing.quantity,
                "gift_wrap": existing.gift_wrap,
                "cart_subtotal": cart.subtotal,
                "cart_total": cart.total,
                **adjustments,
            }

        qcheck = policies.check_quantity_limit(0, quantity)
        if not qcheck["allowed"]:
            return {"error": qcheck["reason"]}

        if gift_wrap and not product.gift_wrap_available:
            return {"error": f"Gift wrapping is not available for {product.name}."}

        ci_id = self.next_cart_item_id()
        ci = CartItem(
            cart_item_id=ci_id,
            customer_id=customer_id,
            product_id=product_id,
            quantity=quantity,
            gift_wrap=gift_wrap,
            variant_id=variant_id,
        )
        self.cart_items[ci_id] = ci
        cart.item_ids.append(ci_id)
        adjustments = self._recompute_cart(cart)

        unit_price = int(product.price) + int((variant or {}).get("price_delta", 0))
        return {
            "status": "added",
            "cart_item_id": ci_id,
            "product_id": product_id,
            "product_name": product.name,
            "variant_id": variant_id,
            "quantity": quantity,
            "gift_wrap": gift_wrap,
            "unit_price": unit_price,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

    def update_cart_item(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        product_id = params.get("product_id", "")
        variant_id = params.get("variant_id") or None
        quantity = params.get("quantity")
        gift_wrap = params.get("gift_wrap")

        if quantity is None and gift_wrap is None:
            return {"error": "Provide at least one of quantity, gift_wrap."}

        cart = self.resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}

        ci, resolve_error = self.resolve_cart_item(cart, product_id, variant_id)
        if resolve_error:
            return {"error": resolve_error}
        assert ci is not None

        if quantity is not None:
            new_qty = int(quantity)
            if new_qty <= 0:
                args = {"customer_id": customer_id, "product_id": product_id}
                if variant_id is not None:
                    args["variant_id"] = variant_id
                return self.remove_from_cart(args)
            qcheck = policies.check_quantity_limit(0, new_qty)
            if not qcheck["allowed"]:
                return {"error": qcheck["reason"]}
            product = self.products.get(product_id)
            if product is not None:
                _variant, stock_error = self.check_product_stock(product, ci.variant_id, new_qty)
                if stock_error:
                    return {"error": stock_error}
            ci.quantity = new_qty

        if gift_wrap is not None:
            new_wrap = bool(gift_wrap)
            if new_wrap:
                product = self.products.get(product_id)
                if product is not None and not product.gift_wrap_available:
                    return {"error": f"Gift wrapping is not available for {product.name}."}
            ci.gift_wrap = new_wrap

        adjustments = self._recompute_cart(cart)
        product = self.products.get(product_id)
        return {
            "status": "updated",
            "cart_item_id": ci.cart_item_id,
            "product_id": product_id,
            "variant_id": ci.variant_id,
            "product_name": product.name if product else None,
            "quantity": ci.quantity,
            "gift_wrap": ci.gift_wrap,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

    def remove_from_cart(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        product_id = params.get("product_id", "")
        variant_id = params.get("variant_id") or None
        cart = self.resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}

        ci, resolve_error = self.resolve_cart_item(cart, product_id, variant_id)
        if resolve_error:
            return {"error": resolve_error}
        assert ci is not None

        cart.item_ids = [iid for iid in cart.item_ids if iid != ci.cart_item_id]
        self.cart_items.pop(ci.cart_item_id, None)
        adjustments = self._recompute_cart(cart)
        return {
            "status": "removed",
            "cart_id": cart.cart_id,
            "product_id": product_id,
            "variant_id": ci.variant_id,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

"""Read-only catalog search, product details, variants, and compatibility."""

from __future__ import annotations

import re
from typing import Any, Callable

from schemas import Product

SEARCH_TOP_N: int = 10
QUERY_TOKEN_WEIGHT: int = 2
QUERY_NAME_BRAND_BOOST: int = 5


def norm_token(s: str) -> str:
    """Lowercase + collapse hyphens/spaces to underscores."""
    return s.lower().replace("-", "_").replace(" ", "_")


def tokenize(s: str) -> list[str]:
    """Lowercase, split on non-alphanumeric, drop empties and length-1 tokens."""
    return [t for t in re.split(r"[^a-z0-9]+", s.lower()) if len(t) > 1]


def build_searchable_text(p: Product) -> str:
    """Compose a normalized text blob over which queries rank."""
    parts: list[str] = [p.name.lower(), (p.brand or "").lower()]
    if p.subcategory:
        parts.append(p.subcategory.lower().replace("_", " "))
        parts.append(norm_token(p.subcategory))
    if p.description:
        parts.append(p.description.lower())
    for spec_key, spec_val in p.specs.items():
        parts.append(spec_key.lower().replace("_", " "))
        parts.append(norm_token(spec_key))
        sval = str(spec_val)
        if not re.match(r"^\s*\d", sval):
            parts.append(sval.lower())
    return " ".join(parts)


class CatalogSearch:
    """Read-only catalog product operations."""

    def __init__(
        self,
        *,
        products: dict[str, Product],
        variant_lookup: Callable[[Product, str | None], dict[str, Any] | None],
    ) -> None:
        self.products = products
        self._variant_lookup = variant_lookup

    def search_products(self, params: dict[str, Any]) -> dict[str, Any]:
        query = (params.get("query") or "").strip()
        category = params.get("category")
        min_price = params.get("min_price")
        max_price = params.get("max_price")
        min_rating = params.get("min_rating")
        in_stock_only = bool(params.get("in_stock_only", False))
        sort_by = params.get("sort_by", "relevance")

        candidates: list[Product] = []
        for p in self.products.values():
            if category and p.category != category:
                continue
            if min_price is not None and p.price < int(min_price):
                continue
            if max_price is not None and p.price > int(max_price):
                continue
            if min_rating is not None and p.rating < float(min_rating):
                continue
            if in_stock_only and not p.in_stock:
                continue
            candidates.append(p)

        if not candidates:
            return {
                "products": [],
                "total_found": 0,
                "note": (
                    "No products match the hard filters "
                    "(category / price / rating / stock). "
                    "Try relaxing them and search again."
                ),
            }

        query_tokens = tokenize(query) if query else []

        scored: list[tuple[int, Product]] = []
        for p in candidates:
            text = build_searchable_text(p)
            score = 0
            if query_tokens:
                hits = sum(1 for tok in query_tokens if re.search(rf"\b{re.escape(tok)}\b", text))
                score += hits * QUERY_TOKEN_WEIGHT
                name_brand = f"{p.name.lower()} {(p.brand or '').lower()}"
                nb_hits = sum(1 for tok in query_tokens if re.search(rf"\b{re.escape(tok)}\b", name_brand))
                score += nb_hits * QUERY_NAME_BRAND_BOOST
            scored.append((score, p))

        if query_tokens:
            scored = [(s, p) for s, p in scored if s > 0]
            if not scored:
                return {
                    "products": [],
                    "total_found": 0,
                    "note": (f"No products match the query '{query}'. Try broader or different keywords."),
                }

        if sort_by == "price_low":
            scored.sort(key=lambda x: x[1].price)
        elif sort_by == "price_high":
            scored.sort(key=lambda x: -x[1].price)
        elif sort_by == "rating":
            scored.sort(key=lambda x: -x[1].rating)
        elif sort_by == "review_count":
            scored.sort(key=lambda x: -x[1].review_count)
        else:
            scored.sort(key=lambda x: (-x[0], -x[1].rating))

        results = [
            {
                "product_id": p.product_id,
                "name": p.name,
                "brand": p.brand,
                "category": p.category,
                "subcategory": p.subcategory,
                "price": p.price,
                "rating": p.rating,
                "review_count": p.review_count,
                "in_stock": p.in_stock,
            }
            for _, p in scored[:SEARCH_TOP_N]
        ]
        return {"products": results, "total_found": len(scored)}

    def get_product_details(self, params: dict[str, Any]) -> dict[str, Any]:
        product_id = params.get("product_id", "")
        product = self.products.get(product_id)
        if not product:
            return {"error": f"Product {product_id} not found."}
        result = product.to_dict()
        result["shipping_estimate"] = f"{product.shipping_days} business days (standard)"
        return result

    def get_variants(self, params: dict[str, Any]) -> dict[str, Any]:
        product_id = params.get("product_id", "")
        product = self.products.get(product_id)
        if not product:
            return {"error": f"Product {product_id} not found."}
        if not product.variants:
            return {
                "product_id": product_id,
                "product_name": product.name,
                "base_price": product.price,
                "variants": [],
                "note": "This product has no variants; no variant_id is needed for add_to_cart.",
            }
        return {
            "product_id": product_id,
            "product_name": product.name,
            "base_price": product.price,
            "variants": [
                {
                    "variant_id": v["variant_id"],
                    "label": v.get("label", ""),
                    "effective_price": product.price + int(v.get("price_delta", 0)),
                    "in_stock": bool(v.get("in_stock", True)),
                    "stock_quantity": int(v.get("stock_quantity", 0)),
                }
                for v in product.variants
            ],
        }


class CompatibilityService:
    """Read-only product compatibility checks."""

    def __init__(self, *, products: dict[str, Product]) -> None:
        self.products = products
        self.canonical_devices: list[str] = sorted({d for p in self.products.values() for d in p.compatible_with})

    def check_compatibility(self, params: dict[str, Any]) -> dict[str, Any]:
        product_id = params.get("product_id", "")
        device_name = (params.get("device_name") or "").strip()
        product = self.products.get(product_id)
        if not product:
            return {"error": f"Product {product_id} not found."}

        device_lower = device_name.lower()
        for compat in product.compatible_with:
            if compat.lower() == device_lower:
                return {
                    "compatible": True,
                    "product_id": product_id,
                    "device": compat,
                    "reason": f"{product.name} is compatible with {compat}.",
                }

        device_known = any(d.lower() == device_lower for d in self.canonical_devices)
        if device_known:
            return {
                "compatible": False,
                "product_id": product_id,
                "device": device_name,
                "reason": (
                    f"{product.name} is not compatible with {device_name}. "
                    f"Compatible devices for this product: "
                    f"{', '.join(product.compatible_with) if product.compatible_with else 'none listed'}."
                ),
            }
        return {
            "compatible": False,
            "product_id": product_id,
            "device": device_name,
            "reason": (
                f"Unknown device name '{device_name}'. "
                f"Canonical devices in this catalog: "
                f"{', '.join(self.canonical_devices) if self.canonical_devices else 'none'}."
            ),
            "canonical_devices": list(self.canonical_devices),
        }

"""Shipping option listing and selection policy."""

from __future__ import annotations

from typing import Any, Callable

import policies
from schemas import Cart, CartItem, Customer, Product
from services.pricing import PricingEngine


class ShippingPolicyService:
    """Own shipping costs, ETA text, eligibility text, and cart selection writes."""

    def __init__(
        self,
        *,
        products: dict[str, Product],
        customers: dict[str, Customer],
        resolve_cart: Callable[[str], Cart | None],
        items_in_cart: Callable[[Cart], list[CartItem]],
        pricing_engine: PricingEngine,
    ) -> None:
        self.products = products
        self.customers = customers
        self._resolve_cart = resolve_cart
        self._items_in_cart = items_in_cart
        self.pricing_engine = pricing_engine

    def _cart_shipping_context(self, cart: Cart) -> tuple[list[CartItem], int, int]:
        items = self._items_in_cart(cart)
        total_item_count = sum(ci.quantity for ci in items)
        max_product_shipping_days = max(
            (self.products[ci.product_id].shipping_days for ci in items if ci.product_id in self.products),
            default=0,
        )
        return items, total_item_count, max_product_shipping_days

    def _eta_description(self, option_name: str, max_product_shipping_days: int) -> str:
        if option_name == "standard":
            eta_days = max(max_product_shipping_days, 1)
            return f"{eta_days} business days"
        if option_name == "express":
            eta_days = max(max_product_shipping_days - 1, 1)
            return f"{eta_days} business days"
        return "next business day"

    def _eligibility(self, option_name: str, customer: Customer, total_item_count: int, cost: int) -> str:
        if option_name == "standard" and total_item_count >= policies.FREE_SHIPPING_ITEM_THRESHOLD:
            return "free — 5+ items in cart"
        if option_name == "express" and customer.tier.lower() in ("gold", "platinum"):
            return f"free — {customer.tier.capitalize()} perk"
        if option_name == "next_day" and customer.tier.lower() == "platinum":
            return "free — Platinum perk"
        return f"${cost}"

    def get_shipping_options(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        cart = self._resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}
        customer = self.customers.get(customer_id)
        if customer is None:
            return {"error": f"Customer {customer_id} not found."}

        _items, total_item_count, max_product_shipping_days = self._cart_shipping_context(cart)

        options: list[dict[str, Any]] = []
        for option_name in policies.VALID_SHIPPING_OPTIONS:
            spec = policies.compute_shipping_cost(option_name, customer.tier, total_item_count)
            options.append(
                {
                    "option": option_name,
                    "cost": spec["cost"],
                    "eta_description": self._eta_description(option_name, max_product_shipping_days),
                    "eligibility": self._eligibility(option_name, customer, total_item_count, spec["cost"]),
                }
            )

        return {
            "options": options,
            "cart_item_count": total_item_count,
            "customer_tier": customer.tier,
        }

    def set_shipping_option(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        option = params.get("option", "")
        cart = self._resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}
        customer = self.customers.get(customer_id)
        if customer is None:
            return {"error": f"Customer {customer_id} not found."}
        if not cart.item_ids:
            return {"error": "Cart is empty — cannot set shipping on an empty cart."}

        _items, total_item_count, _max_product_shipping_days = self._cart_shipping_context(cart)
        spec = policies.compute_shipping_cost(option, customer.tier, total_item_count)
        if not spec["valid"]:
            return {"error": spec["reason"]}

        cart.shipping_option = option
        cart.shipping_cost = int(spec["cost"])
        adjustments = self.pricing_engine.recompute_cart(cart)
        return {
            "status": "set",
            "shipping_option": option,
            "shipping_cost": cart.shipping_cost,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

#!/usr/bin/env python3
"""STATE-Bench portable domain skill CLI.

Commands:
  tools                                      Print the domain tool schemas (OpenAI function format).
  call  <tool> --args '<json>' [--now <iso>]  Run a tool against the unified world.db (reads/mutates it).
  reset                                      Clear this skill's multi-step session gates (no-op on data).

State model: domain data lives in the unified per-task `world.db` (seeded fresh
into /workspace by the runner). `ENV_DATA_CLASS.load()` reads this skill's scoped
slice from world.db and `.save()` writes mutations straight back — there is no
db.json seed and no state.json working copy. Multi-step gates (policy-check ->
preview -> confirm) still persist in a local `session.json` under the workspace
(fresh per task since skills upload clean into each sandbox). `reset` clears those
gates; the data itself is re-seeded per task by the runner. By default the session
file lives in `<skill>/.state/`; override with --workspace.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from domain_meta import DEFAULT_NOW, DEFAULT_USER, ENV_CLASS, ENV_DATA_CLASS, SAVE_MAP  # noqa: E402
from tools import TOOL_SCHEMAS, WRITE_TOOL_NAMES  # noqa: E402


# --- session-state (sets/tuples) JSON codec -------------------------------
def _enc(o):
    if isinstance(o, set):
        return {"__set__": [_enc(x) for x in o]}
    if isinstance(o, tuple):
        return {"__tuple__": [_enc(x) for x in o]}
    if isinstance(o, dict):
        return {k: _enc(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_enc(x) for x in o]
    return o


def _dec(o):
    if isinstance(o, dict):
        if set(o.keys()) == {"__set__"}:
            return {_dec(x) for x in o["__set__"]}
        if set(o.keys()) == {"__tuple__"}:
            return tuple(_dec(x) for x in o["__tuple__"])
        return {k: _dec(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_dec(x) for x in o]
    return o


def _emit(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False, indent=2))
    sys.exit(code)


def _workspace(args) -> Path:
    return Path(args.workspace) if getattr(args, "workspace", None) else (HERE / ".state")


def _seed_if_needed(ws: Path) -> Path:
    """Ensure the workspace dir exists and return the (session-only) state path.

    Domain data now lives in world.db (see schemas.py), so there is no db.json to
    copy; this just guarantees the workspace dir for session.json.
    """
    ws.mkdir(parents=True, exist_ok=True)
    return ws / "state.json"


def cmd_tools(_args):
    _emit({"write_tools": WRITE_TOOL_NAMES, "default_user": DEFAULT_USER, "now": DEFAULT_NOW, "tools": TOOL_SCHEMAS})


def cmd_reset(args):
    ws = _workspace(args)
    for name in ("state.json", "session.json"):
        p = ws / name
        if p.exists():
            p.unlink()
    _emit({"ok": True, "reset": True, "workspace": str(ws),
           "note": "session gates cleared; domain data is re-seeded per task from world.db"})


def cmd_call(args):
    ws = _workspace(args)
    state_path = _seed_if_needed(ws)
    now = args.now or DEFAULT_NOW
    try:
        params = json.loads(args.args) if args.args else {}
    except json.JSONDecodeError as e:
        _emit({"error": f"--args must be valid JSON: {e}"}, 1)
    if not isinstance(params, dict):
        _emit({"error": "--args must be a JSON object"}, 1)

    env_data = ENV_DATA_CLASS.load(state_path)
    env = ENV_CLASS(env_data, now=now)

    session_path = ws / "session.json"
    if session_path.exists():
        for k, v in _dec(json.loads(session_path.read_text())).items():
            setattr(env, k, v)

    handler = env.tool_handlers.get(args.tool)
    if handler is None:
        _emit({"error": f"Unknown tool '{args.tool}'. Run `tools` to list available tools."}, 1)

    try:
        result = handler(params)
    except Exception as e:  # domain handlers raise on bad input; surface as JSON
        _emit({"error": f"{type(e).__name__}: {e}"}, 1)

    # Persist mutated DB (rebuild EnvironmentData from live indexes so created rows are captured).
    rebuilt = ENV_DATA_CLASS(**{field: list(getattr(env, attr).values()) for field, attr in SAVE_MAP.items()})
    rebuilt.save(state_path)

    # Persist multi-step session flags (policy-check / preview gates).
    sess_out = {k: v for k, v in vars(env).items() if k.startswith("_")}
    session_path.write_text(json.dumps(_enc(sess_out), indent=2))

    is_write = args.tool in WRITE_TOOL_NAMES
    _emit({"tool": args.tool, "is_write": is_write, "result": result})


def main():
    p = argparse.ArgumentParser(description="STATE-Bench portable domain skill CLI")
    sub = p.add_subparsers(dest="cmd", required=True)
    sub.add_parser("tools").set_defaults(fn=cmd_tools)
    pr = sub.add_parser("reset")
    pr.add_argument("--workspace", default=None)
    pr.set_defaults(fn=cmd_reset)
    pc = sub.add_parser("call")
    pc.add_argument("tool")
    pc.add_argument("--args", default="{}")
    pc.add_argument("--now", default=None)
    pc.add_argument("--workspace", default=None)
    pc.set_defaults(fn=cmd_call)
    a = p.parse_args()
    a.fn(a)


if __name__ == "__main__":
    main()

"""Cart lookup and mutation operations."""

from __future__ import annotations

import re
from typing import Any

import policies
from schemas import Cart, CartItem, Product
from services.pricing import PricingEngine


class CartService:
    """Own cart item lookup, stock checks, ID generation, and mutations."""

    def __init__(
        self,
        *,
        products: dict[str, Product],
        carts_by_id: dict[str, Cart],
        cart_items: dict[str, CartItem],
    ) -> None:
        self.products = products
        self.carts_by_id = carts_by_id
        self.cart_items = cart_items
        self.pricing_engine: PricingEngine | None = None
        self._next_ci_seq = self._initial_ci_seq()

    def set_pricing_engine(self, pricing_engine: PricingEngine) -> None:
        self.pricing_engine = pricing_engine

    def _recompute_cart(self, cart: Cart) -> dict[str, Any]:
        assert self.pricing_engine is not None
        return self.pricing_engine.recompute_cart(cart)

    def _initial_ci_seq(self) -> int:
        max_seq = 0
        for ciid in self.cart_items:
            m = re.match(r"^CI-(\d+)$", ciid)
            if m:
                max_seq = max(max_seq, int(m.group(1)))
        return max_seq + 1

    def next_cart_item_id(self) -> str:
        ciid = f"CI-{self._next_ci_seq:04d}"
        self._next_ci_seq += 1
        return ciid

    def resolve_cart(self, customer_id: str) -> Cart | None:
        return self.carts_by_id.get(f"CART-{customer_id}")

    def items_in_cart(self, cart: Cart) -> list[CartItem]:
        return [self.cart_items[iid] for iid in cart.item_ids if iid in self.cart_items]

    def resolve_cart_item(
        self,
        cart: Cart,
        product_id: str,
        variant_id: str | None = None,
    ) -> tuple[CartItem | None, str | None]:
        matches = [
            ci
            for ci in self.items_in_cart(cart)
            if ci.product_id == product_id and (variant_id is None or ci.variant_id == variant_id)
        ]
        if not matches:
            if variant_id is not None:
                return None, f"Product {product_id} with variant {variant_id} not in cart."
            return None, f"Product {product_id} not in cart."
        if variant_id is None and len(matches) > 1:
            variants = ", ".join(sorted(ci.variant_id or "<none>" for ci in matches))
            return None, f"Multiple variants of product {product_id} are in cart ({variants}); provide variant_id."
        return matches[0], None

    def variant_lookup(self, product: Product, variant_id: str | None) -> dict[str, Any] | None:
        """Find a variant dict on a product by id."""
        if not variant_id or not product.variants:
            return None
        for v in product.variants:
            if v.get("variant_id") == variant_id:
                return v
        return None

    def check_product_stock(
        self,
        product: Product,
        variant_id: str | None,
        requested_quantity: int,
    ) -> tuple[dict[str, Any] | None, str | None]:
        if product.variants:
            if not variant_id:
                return None, (
                    f"{product.name} requires a variant selection. Check product details or variants to see options."
                )
            variant = self.variant_lookup(product, variant_id)
            if variant is None:
                return None, f"Variant '{variant_id}' not found for {product.name}."
            stock = policies.check_stock(
                bool(variant.get("in_stock", True)),
                int(variant.get("stock_quantity", 0)),
                requested_quantity,
            )
            if not stock["available"]:
                return None, stock["reason"]
            return variant, None
        if variant_id:
            return None, f"{product.name} does not have variants."
        stock = policies.check_stock(product.in_stock, product.stock_quantity, requested_quantity)
        if not stock["available"]:
            return None, stock["reason"]
        return None, None

    def add_to_cart(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        product_id = params.get("product_id", "")
        quantity = int(params.get("quantity", 1) or 1)
        gift_wrap = bool(params.get("gift_wrap", False))
        variant_id = params.get("variant_id") or None

        if quantity <= 0:
            return {"error": "quantity must be a positive integer."}

        cart = self.resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}

        product = self.products.get(product_id)
        if product is None:
            return {"error": f"Product {product_id} not found."}

        variant, stock_error = self.check_product_stock(product, variant_id, quantity)
        if stock_error:
            return {"error": stock_error}

        existing: CartItem | None = None
        for ci in self.items_in_cart(cart):
            if ci.product_id == product_id and ci.variant_id == variant_id:
                existing = ci
                break

        if existing is not None:
            final_quantity = existing.quantity + quantity
            qcheck = policies.check_quantity_limit(existing.quantity, quantity)
            if not qcheck["allowed"]:
                return {"error": qcheck["reason"]}
            _variant, stock_error = self.check_product_stock(product, variant_id, final_quantity)
            if stock_error:
                return {"error": stock_error}
            existing.quantity += quantity
            if gift_wrap:
                existing.gift_wrap = True
            adjustments = self._recompute_cart(cart)
            return {
                "status": "updated",
                "cart_item_id": existing.cart_item_id,
                "product_id": product_id,
                "product_name": product.name,
                "variant_id": existing.variant_id,
                "quantity": existing.quantity,
                "gift_wrap": existing.gift_wrap,
                "cart_subtotal": cart.subtotal,
                "cart_total": cart.total,
                **adjustments,
            }

        qcheck = policies.check_quantity_limit(0, quantity)
        if not qcheck["allowed"]:
            return {"error": qcheck["reason"]}

        if gift_wrap and not product.gift_wrap_available:
            return {"error": f"Gift wrapping is not available for {product.name}."}

        ci_id = self.next_cart_item_id()
        ci = CartItem(
            cart_item_id=ci_id,
            customer_id=customer_id,
            product_id=product_id,
            quantity=quantity,
            gift_wrap=gift_wrap,
            variant_id=variant_id,
        )
        self.cart_items[ci_id] = ci
        cart.item_ids.append(ci_id)
        adjustments = self._recompute_cart(cart)

        unit_price = int(product.price) + int((variant or {}).get("price_delta", 0))
        return {
            "status": "added",
            "cart_item_id": ci_id,
            "product_id": product_id,
            "product_name": product.name,
            "variant_id": variant_id,
            "quantity": quantity,
            "gift_wrap": gift_wrap,
            "unit_price": unit_price,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

    def update_cart_item(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        product_id = params.get("product_id", "")
        variant_id = params.get("variant_id") or None
        quantity = params.get("quantity")
        gift_wrap = params.get("gift_wrap")

        if quantity is None and gift_wrap is None:
            return {"error": "Provide at least one of quantity, gift_wrap."}

        cart = self.resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}

        ci, resolve_error = self.resolve_cart_item(cart, product_id, variant_id)
        if resolve_error:
            return {"error": resolve_error}
        assert ci is not None

        if quantity is not None:
            new_qty = int(quantity)
            if new_qty <= 0:
                args = {"customer_id": customer_id, "product_id": product_id}
                if variant_id is not None:
                    args["variant_id"] = variant_id
                return self.remove_from_cart(args)
            qcheck = policies.check_quantity_limit(0, new_qty)
            if not qcheck["allowed"]:
                return {"error": qcheck["reason"]}
            product = self.products.get(product_id)
            if product is not None:
                _variant, stock_error = self.check_product_stock(product, ci.variant_id, new_qty)
                if stock_error:
                    return {"error": stock_error}
            ci.quantity = new_qty

        if gift_wrap is not None:
            new_wrap = bool(gift_wrap)
            if new_wrap:
                product = self.products.get(product_id)
                if product is not None and not product.gift_wrap_available:
                    return {"error": f"Gift wrapping is not available for {product.name}."}
            ci.gift_wrap = new_wrap

        adjustments = self._recompute_cart(cart)
        product = self.products.get(product_id)
        return {
            "status": "updated",
            "cart_item_id": ci.cart_item_id,
            "product_id": product_id,
            "variant_id": ci.variant_id,
            "product_name": product.name if product else None,
            "quantity": ci.quantity,
            "gift_wrap": ci.gift_wrap,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

    def remove_from_cart(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        product_id = params.get("product_id", "")
        variant_id = params.get("variant_id") or None
        cart = self.resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}

        ci, resolve_error = self.resolve_cart_item(cart, product_id, variant_id)
        if resolve_error:
            return {"error": resolve_error}
        assert ci is not None

        cart.item_ids = [iid for iid in cart.item_ids if iid != ci.cart_item_id]
        self.cart_items.pop(ci.cart_item_id, None)
        adjustments = self._recompute_cart(cart)
        return {
            "status": "removed",
            "cart_id": cart.cart_id,
            "product_id": product_id,
            "variant_id": ci.variant_id,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

"""Shipping option listing and selection policy."""

from __future__ import annotations

from typing import Any, Callable

import policies
from schemas import Cart, CartItem, Customer, Product
from services.pricing import PricingEngine


class ShippingPolicyService:
    """Own shipping costs, ETA text, eligibility text, and cart selection writes."""

    def __init__(
        self,
        *,
        products: dict[str, Product],
        customers: dict[str, Customer],
        resolve_cart: Callable[[str], Cart | None],
        items_in_cart: Callable[[Cart], list[CartItem]],
        pricing_engine: PricingEngine,
    ) -> None:
        self.products = products
        self.customers = customers
        self._resolve_cart = resolve_cart
        self._items_in_cart = items_in_cart
        self.pricing_engine = pricing_engine

    def _cart_shipping_context(self, cart: Cart) -> tuple[list[CartItem], int, int]:
        items = self._items_in_cart(cart)
        total_item_count = sum(ci.quantity for ci in items)
        max_product_shipping_days = max(
            (self.products[ci.product_id].shipping_days for ci in items if ci.product_id in self.products),
            default=0,
        )
        return items, total_item_count, max_product_shipping_days

    def _eta_description(self, option_name: str, max_product_shipping_days: int) -> str:
        if option_name == "standard":
            eta_days = max(max_product_shipping_days, 1)
            return f"{eta_days} business days"
        if option_name == "express":
            eta_days = max(max_product_shipping_days - 1, 1)
            return f"{eta_days} business days"
        return "next business day"

    def _eligibility(self, option_name: str, customer: Customer, total_item_count: int, cost: int) -> str:
        if option_name == "standard" and total_item_count >= policies.FREE_SHIPPING_ITEM_THRESHOLD:
            return "free — 5+ items in cart"
        if option_name == "express" and customer.tier.lower() in ("gold", "platinum"):
            return f"free — {customer.tier.capitalize()} perk"
        if option_name == "next_day" and customer.tier.lower() == "platinum":
            return "free — Platinum perk"
        return f"${cost}"

    def get_shipping_options(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        cart = self._resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}
        customer = self.customers.get(customer_id)
        if customer is None:
            return {"error": f"Customer {customer_id} not found."}

        _items, total_item_count, max_product_shipping_days = self._cart_shipping_context(cart)

        options: list[dict[str, Any]] = []
        for option_name in policies.VALID_SHIPPING_OPTIONS:
            spec = policies.compute_shipping_cost(option_name, customer.tier, total_item_count)
            options.append(
                {
                    "option": option_name,
                    "cost": spec["cost"],
                    "eta_description": self._eta_description(option_name, max_product_shipping_days),
                    "eligibility": self._eligibility(option_name, customer, total_item_count, spec["cost"]),
                }
            )

        return {
            "options": options,
            "cart_item_count": total_item_count,
            "customer_tier": customer.tier,
        }

    def set_shipping_option(self, params: dict[str, Any]) -> dict[str, Any]:
        customer_id = params.get("customer_id", "")
        option = params.get("option", "")
        cart = self._resolve_cart(customer_id)
        if cart is None:
            return {"error": f"No cart for customer {customer_id}."}
        customer = self.customers.get(customer_id)
        if customer is None:
            return {"error": f"Customer {customer_id} not found."}
        if not cart.item_ids:
            return {"error": "Cart is empty — cannot set shipping on an empty cart."}

        _items, total_item_count, _max_product_shipping_days = self._cart_shipping_context(cart)
        spec = policies.compute_shipping_cost(option, customer.tier, total_item_count)
        if not spec["valid"]:
            return {"error": spec["reason"]}

        cart.shipping_option = option
        cart.shipping_cost = int(spec["cost"])
        adjustments = self.pricing_engine.recompute_cart(cart)
        return {
            "status": "set",
            "shipping_option": option,
            "shipping_cost": cart.shipping_cost,
            "cart_subtotal": cart.subtotal,
            "cart_total": cart.total,
            **adjustments,
        }

"""Vendored domain-agnostic base classes (from state_bench). Stdlib only."""
from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class DictMixin:
    """Standard to_dict/from_dict for flat dataclasses."""

    def to_dict(self) -> dict[str, Any]:
        return {fn: getattr(self, fn) for fn in self.__dataclass_fields__}

    @classmethod
    def from_dict(cls, data: dict[str, Any]):
        return cls(**{k: v for k, v in data.items() if k in cls.__dataclass_fields__})


class BaseEnvironment(ABC):
    """Abstract base for domain environments."""

    def __init__(self, env_data: Any, now: str):
        self.now = now

    @property
    @abstractmethod
    def tool_handlers(self) -> dict[str, Callable]:
        ...

    @abstractmethod
    def get_full_snapshot(self) -> dict[str, dict[str, dict[str, Any]]]:
        ...

    @staticmethod
    def parse_bool(value: Any) -> bool | None:
        if value is None:
            return None
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.lower() in ("true", "1", "yes")
        return bool(value)

"""Deterministic policy engine for the shopping assistant domain.

All functions are pure — no randomness, no side effects, no calls to
`datetime.now()` (all time comparisons use an explicit `now` parameter
passed from the environment).

Two kinds of artifacts live here:
1. Pure functions that back write-tool behavior (validate_promo, check_stock,
   check_quantity_limit, compute_gift_wrap_fee, etc.).
2. `POLICY_TEXTS` — a canonical dict of human-readable policy statements.
   `get_policies(topic)` returns these verbatim. Whether the agent verbalizes
   them to the customer is LLM-judged via `task_requirements` — there is no
   process gate that tracks which topics have been fetched.
"""

from __future__ import annotations

from collections import Counter
from datetime import datetime
from typing import Any

# ---------------------------------------------------------------------------
# Tunable constants
# ---------------------------------------------------------------------------

GIFT_WRAP_FEE_PER_ITEM: int = 5

QUANTITY_LIMIT: int = 3  # per-product cap per cart

LOYALTY_POINTS_RATE: dict[str, int] = {
    "platinum": 3,
    "gold": 2,
    "standard": 1,
}

BRAND_BUNDLE_PCT: float = 0.03  # 3% off same-brand 2+ items
CATEGORY_BUNDLE_PCT: float = 0.05  # 5% off same-category 3+ items
WELCOME_DISCOUNT_PCT: float = 0.05  # 5% off first order
BACKORDER_DEPOSIT_PCT: float = 0.10  # 10% deposit to backorder
MAX_PROMO_CODES_PER_CART: int = 1


# ---------------------------------------------------------------------------
# Promo validation (used by apply_promo)
# ---------------------------------------------------------------------------


def check_promo_stack(existing_codes: list[str], promo_code: str) -> dict[str, Any]:
    """Enforce the one-promo-code-per-cart rule for apply_promo."""
    if promo_code in existing_codes or len(existing_codes) < MAX_PROMO_CODES_PER_CART:
        return {"valid": True}

    existing = existing_codes[0]
    return {
        "valid": False,
        "reason": (
            "Only one promo code can be applied per cart. "
            f"Remove existing promo code {existing} before applying {promo_code}."
        ),
    }


def validate_promo(
    promo_code: str,
    promo: dict[str, Any] | None,
    cart_subtotal: int,
    cart_categories: list[str],
    now: str,
) -> dict[str, Any]:
    """Validate a promo code against current cart state.

    Rules applied in order:
    - Promo must exist.
    - Promo must be active.
    - Must not be past expiry_date.
    - All cart categories must satisfy category_restriction if set.
    - Cart subtotal must meet min_purchase.
    """
    if promo is None:
        return {"valid": False, "reason": f"Promo code '{promo_code}' not found."}

    if not promo.get("active", False):
        return {"valid": False, "reason": "This promo code is no longer active."}

    expiry = promo.get("expiry_date") or ""
    if expiry:
        now_dt = datetime.fromisoformat(now)
        exp_dt = datetime.fromisoformat(expiry)
        if now_dt > exp_dt:
            return {"valid": False, "reason": f"Promo code expired on {expiry}."}

    cat_restriction = promo.get("category_restriction")
    if cat_restriction:
        invalid_cats = [c for c in cart_categories if c not in cat_restriction]
        if invalid_cats:
            return {
                "valid": False,
                "reason": (
                    f"Promo applies only to {', '.join(cat_restriction)}. "
                    f"Cart contains {', '.join(sorted(set(invalid_cats)))} items."
                ),
            }

    min_purchase = int(promo.get("min_purchase") or 0)
    if cart_subtotal < min_purchase:
        return {
            "valid": False,
            "reason": f"Minimum purchase of ${min_purchase} required. Cart subtotal: ${cart_subtotal}.",
        }

    discount_type = promo.get("discount_type", "percentage")
    discount_value = int(promo.get("discount_value") or 0)
    max_discount = int(promo.get("max_discount") or 0)

    if discount_type == "percentage":
        discount = int(cart_subtotal * discount_value / 100)
    else:
        discount = discount_value

    if max_discount > 0:
        discount = min(discount, max_discount)

    return {
        "valid": True,
        "discount_amount": discount,
        "reason": f"Promo applied: {promo.get('description', promo_code)}",
    }


# ---------------------------------------------------------------------------
# Stock & quantity (used by add_to_cart / update_cart_item)
# ---------------------------------------------------------------------------


def check_stock(
    product_in_stock: bool,
    stock_quantity: int,
    requested_quantity: int,
) -> dict[str, Any]:
    """Check whether `requested_quantity` can be fulfilled from stock."""
    if not product_in_stock:
        return {"available": False, "reason": "Product is currently out of stock."}
    if requested_quantity > stock_quantity:
        return {
            "available": False,
            "reason": f"Only {stock_quantity} units available. Requested: {requested_quantity}.",
        }
    return {"available": True, "quantity": requested_quantity}


def check_quantity_limit(
    current_quantity: int,
    requested_add: int,
) -> dict[str, Any]:
    """Enforce the per-product cap per cart (anti-hoarding)."""
    total = current_quantity + requested_add
    if total > QUANTITY_LIMIT:
        return {
            "allowed": False,
            "limit": QUANTITY_LIMIT,
            "current": current_quantity,
            "reason": (f"Maximum {QUANTITY_LIMIT} of the same product per cart. You already have {current_quantity}."),
        }
    return {"allowed": True, "total_after_add": total}


# ---------------------------------------------------------------------------
# Gift wrap
# ---------------------------------------------------------------------------


def compute_gift_wrap_fee(wrapped_item_count: int) -> int:
    """Flat per-wrapped-item fee. No threshold — any item can be wrapped."""
    return wrapped_item_count * GIFT_WRAP_FEE_PER_ITEM


# ---------------------------------------------------------------------------
# Loyalty points (info-only — agent verbalizes; no state write)
# ---------------------------------------------------------------------------


def compute_loyalty_points(cart_total: int, tier: str) -> dict[str, Any]:
    """Points earned on a purchase at the given tier's rate."""
    rate = LOYALTY_POINTS_RATE.get(tier, 1)
    return {"points_earned": cart_total * rate, "rate": rate, "tier": tier}


# Loyalty redemption constants
LOYALTY_REDEMPTION_RATE_POINTS_PER_DOLLAR: int = 100
LOYALTY_REDEMPTION_MIN_POINTS: int = 500
LOYALTY_REDEMPTION_CAP_PCT: float = 0.5  # 50% of cart total


def validate_redemption(balance: int, requested_points: int, cart_total: int) -> dict[str, Any]:
    """Validate a loyalty-point redemption request.

    Returns {valid, reason, discount_amount (cents→dollars), points_debited}.
    """
    if requested_points <= 0:
        return {
            "valid": False,
            "reason": "requested_points must be positive.",
            "discount_amount": 0,
            "points_debited": 0,
        }
    if requested_points < LOYALTY_REDEMPTION_MIN_POINTS:
        return {
            "valid": False,
            "reason": f"Minimum redemption is {LOYALTY_REDEMPTION_MIN_POINTS} points (${LOYALTY_REDEMPTION_MIN_POINTS // LOYALTY_REDEMPTION_RATE_POINTS_PER_DOLLAR}).",
            "discount_amount": 0,
            "points_debited": 0,
        }
    if requested_points > balance:
        return {
            "valid": False,
            "reason": f"Insufficient balance: have {balance} points, requested {requested_points}.",
            "discount_amount": 0,
            "points_debited": 0,
        }
    # Cap at 50% of cart total.
    max_discount = int(cart_total * LOYALTY_REDEMPTION_CAP_PCT)
    requested_dollars = requested_points // LOYALTY_REDEMPTION_RATE_POINTS_PER_DOLLAR
    discount = min(requested_dollars, max_discount)
    if discount <= 0:
        return {
            "valid": False,
            "reason": "Cart total is too low for redemption (50% cap too small to cover minimum).",
            "discount_amount": 0,
            "points_debited": 0,
        }
    points_debited = discount * LOYALTY_REDEMPTION_RATE_POINTS_PER_DOLLAR
    return {
        "valid": True,
        "reason": "Redemption validated.",
        "discount_amount": discount,
        "points_debited": points_debited,
    }


# ---------------------------------------------------------------------------
# Shipping options
# ---------------------------------------------------------------------------

VALID_SHIPPING_OPTIONS: list[str] = ["standard", "express", "next_day"]
STANDARD_SHIPPING_FEE: int = 6
EXPRESS_SHIPPING_FEE: int = 12  # express paid rate when not free-tier
NEXT_DAY_SHIPPING_FEE: int = 15  # next-day paid rate when not Platinum
FREE_SHIPPING_ITEM_THRESHOLD: int = 5  # 5+ units in cart -> free standard


def compute_shipping_cost(option: str, tier: str, total_item_count: int) -> dict[str, Any]:
    """Return {valid, reason, cost, eta_days_delta} for a shipping option.

    eta_days_delta: 0 for standard (use product.shipping_days as-is), -1 for
    express (one day faster), and -99 for next-day (caller special-cases to
    'next business day'). Callers surface ETAs; this function owns only the
    cost + validity.
    """
    tier = (tier or "standard").lower()
    if option not in VALID_SHIPPING_OPTIONS:
        return {
            "valid": False,
            "reason": f"Unknown shipping option {option!r}. Valid: {VALID_SHIPPING_OPTIONS}.",
            "cost": 0,
            "eta_days_delta": 0,
        }

    if option == "standard":
        cost = 0 if total_item_count >= FREE_SHIPPING_ITEM_THRESHOLD else STANDARD_SHIPPING_FEE
        return {"valid": True, "reason": "", "cost": cost, "eta_days_delta": 0}

    if option == "express":
        cost = 0 if tier in ("gold", "platinum") else EXPRESS_SHIPPING_FEE
        return {"valid": True, "reason": "", "cost": cost, "eta_days_delta": -1}

    # next_day
    cost = 0 if tier == "platinum" else NEXT_DAY_SHIPPING_FEE
    return {"valid": True, "reason": "", "cost": cost, "eta_days_delta": -99}


# ---------------------------------------------------------------------------
# Bundle bonuses (info-only — agent verbalizes; no state write)
# ---------------------------------------------------------------------------


def compute_brand_bundle_bonus(items: list[dict[str, Any]]) -> dict[str, Any]:
    """Same-brand 2+ items → 3% off those items' line totals.

    Each item dict must carry: brand, unit_price, quantity.
    """
    brand_counts = Counter(item.get("brand", "") for item in items if item.get("brand"))
    bonus_brands = [b for b, c in brand_counts.items() if c >= 2]
    discount = 0
    for item in items:
        if item.get("brand") in bonus_brands:
            discount += int(item.get("unit_price", 0) * item.get("quantity", 1) * BRAND_BUNDLE_PCT)
    return {
        "has_brand_bonus": bool(bonus_brands),
        "bonus_brands": bonus_brands,
        "brand_discount": discount,
    }


def compute_category_bundle(items: list[dict[str, Any]]) -> dict[str, Any]:
    """Same-category 3+ items → 5% off those items' line totals.

    Each item dict must carry: category, unit_price, quantity.
    """
    category_counts = Counter(item.get("category", "") for item in items if item.get("category"))
    bundle_cats = [c for c, count in category_counts.items() if count >= 3]
    discount = 0
    for item in items:
        if item.get("category") in bundle_cats:
            discount += int(item.get("unit_price", 0) * item.get("quantity", 1) * CATEGORY_BUNDLE_PCT)
    return {
        "has_category_bundle": bool(bundle_cats),
        "bundle_categories": bundle_cats,
        "category_discount": discount,
    }


# ---------------------------------------------------------------------------
# Welcome discount (info-only)
# ---------------------------------------------------------------------------


def check_welcome_discount(is_first_time: bool, cart_subtotal: int) -> dict[str, Any]:
    """First-time customers get 5% off; caller decides whether to verbalize."""
    if is_first_time:
        discount = int(cart_subtotal * WELCOME_DISCOUNT_PCT)
        return {
            "eligible": True,
            "discount_pct": int(WELCOME_DISCOUNT_PCT * 100),
            "discount_amount": discount,
            "reason": "First-time customer: 5% welcome discount applies.",
        }
    return {"eligible": False, "reason": "Welcome discount is for first-time customers only."}


# ---------------------------------------------------------------------------
# Backorder (info-only)
# ---------------------------------------------------------------------------


def compute_backorder_deposit(product_price: int) -> dict[str, Any]:
    deposit = int(product_price * BACKORDER_DEPOSIT_PCT)
    return {
        "deposit": deposit,
        "product_price": product_price,
        "estimated_restock": "2-4 weeks",
        "reason": f"Backorder available. 10% deposit (${deposit}) required. Estimated restock: 2-4 weeks.",
    }


# ---------------------------------------------------------------------------
# Price drop alerts (info-only)
# ---------------------------------------------------------------------------


def check_price_drop(current_price: int, previous_price: int | None) -> dict[str, Any]:
    if previous_price is not None and previous_price > current_price:
        savings = previous_price - current_price
        pct = int(savings / previous_price * 100)
        return {
            "has_drop": True,
            "previous_price": previous_price,
            "current_price": current_price,
            "savings": savings,
            "drop_pct": pct,
            "reason": f"Price dropped from ${previous_price} to ${current_price} — save ${savings} ({pct}% off).",
        }
    return {"has_drop": False}


